<script setup>
import { ref,computed,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { currentShop } from '../stores/shop'
import { merchantVehicleService as api } from '../services/merchant'
import { useReferences } from '../composables/useReferences'
import { vehiclePayload,major } from '../utils/pro'
import { notify } from '../stores/toasts'
import AsyncState from '../components/AsyncState.vue'
import FormError from '../components/FormError.vue'
import PhotoManager from '../components/PhotoManager.vue'
import ProfileLocation from '../components/ProfileLocation.vue'
const route=useRoute(),router=useRouter(),{references,state:refState,error:refError,load:loadReferences}=useReferences()
const record=ref(null),step=ref(0),busy=ref(false),loading=ref(false),error=ref(null),photos=ref([])
const shop=computed(()=>record.value?.shop||currentShop.value)
const fields=ref({brand_id:'',vehicle_model_id:'',category_id:'',trim:'',year:new Date().getFullYear(),condition:'used',color:'',offer:'sale',sale:'',rent:'',mileage_km:'',fuel:'petrol',transmission:'automatic',engine:'',horsepower:'',doors:'',seats:'',description:'',feature_ids:[],country_code:shop.value?.location.country.code||'',city_id:shop.value?.location.city.id||'',district_id:shop.value?.location.district?.id||'',latitude:'',longitude:''})
const steps=['Identité','Offre','Caractéristiques','Localisation','Photos & publication']
const models=computed(()=>references.models.filter(m=>m.brand_id===fields.value.brand_id))
async function load(){if(!route.params.id)return;loading.value=true;error.value=null;try{record.value=(await api.get(route.params.id)).data;const v=record.value;fields.value={...fields.value,...Object.fromEntries(['trim','year','condition','color','mileage_km','fuel','transmission','engine','horsepower','doors','seats','description'].map(k=>[k,v[k]??''])),brand_id:v.brand.id,vehicle_model_id:v.model.id,category_id:v.category.id,offer:v.offer_types.length===2?'both':v.offer_types.includes('sale')?'sale':'rental',sale:major(v.sale_price),rent:major(v.rental_daily_price),feature_ids:v.features.map(f=>f.id),country_code:v.location.country.code,city_id:v.location.city.id,district_id:v.location.district?.id||'',latitude:v.location.latitude??'',longitude:v.location.longitude??''}}catch(e){error.value=e}finally{loading.value=false}}
async function refreshPhotos(){try{record.value=(await api.get(record.value.id)).data}catch(e){error.value=e}}
async function save(publish){if(busy.value||!shop.value)return;busy.value=true;error.value=null;try{
 const payload=vehiclePayload(fields.value,shop.value,!!record.value)
 record.value=(await(record.value?api.update(record.value.id,payload):api.create(payload))).data
 while(photos.value.length){await api.upload(record.value.id,photos.value[0]);photos.value=photos.value.slice(1)}
 await api.status(record.value.id,{publication_status:publish?'published':'draft'})
 notify(route.params.id?'Véhicule modifié.':'Véhicule ajouté.')
 await router.push('/vehicles/'+record.value.id)
}catch(e){error.value=e;if(record.value){try{await refreshPhotos()}catch{/* Preserve the original actionable error. */}}}finally{busy.value=false}}
onMounted(load)
</script><template><RouterLink class="back" to="/vehicles">← Retour au parc</RouterLink><div class="page-heading"><div><h1>{{ route.params.id?'Modifier le véhicule':'Ajouter un véhicule' }}</h1><p class="lead">{{ shop?.name }} · Une annonce claire, une offre précise.</p></div></div><AsyncState :busy="loading" :error="loading?null:(!record && route.params.id?error:null)" @retry="load"><div v-if="!shop" class="panel empty">Aucune boutique accessible. <RouterLink to="/dashboard">Retour au tableau de bord</RouterLink></div><template v-else><nav class="steps" aria-label="Étapes du formulaire"><button v-for="(name,i) in steps" :key="name" :aria-current="step===i?'step':undefined" :class="{active:step===i}" :disabled="busy" @click="step=i"><span>{{ i+1 }}</span>{{ name }}</button></nav><div v-if="refState==='error'" class="notice">{{ refError }} <button @click="loadReferences">Réessayer les référentiels</button></div><FormError :error="error"/><form class="panel vehicle-form" @submit.prevent="save(false)"><fieldset :disabled="busy"><template v-if="step===0"><h2>Identité du véhicule</h2><div class="form-grid"><label>Marque<select v-model="fields.brand_id" required @change="fields.vehicle_model_id=''"><option value="">Choisir une marque</option><option v-for="b in references.brands" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>Modèle<select v-model="fields.vehicle_model_id" required :disabled="!fields.brand_id"><option value="">Choisir un modèle</option><option v-for="m in models" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><label>Version / finition<input v-model="fields.trim" maxlength="100"/></label><label>Année<input v-model="fields.year" type="number" min="1900" :max="new Date().getFullYear()+1" required/></label><label>État<select v-model="fields.condition"><option value="used">Occasion</option><option value="new">Neuf</option></select></label><label>Catégorie<select v-model="fields.category_id" required><option value="">Choisir une catégorie</option><option v-for="c in references.categories" :key="c.id" :value="c.id">{{ c.label }}</option></select></label><label>Couleur<input v-model="fields.color" maxlength="80"/></label></div></template><template v-if="step===1"><h2>Votre offre</h2><div class="offer-options"><label v-for="[value,text] in [['sale','À vendre'],['rental','À louer'],['both','Vente + location']]" :key="value"><input v-model="fields.offer" type="radio" :value="value" name="offer"/>{{ text }}</label></div><div class="form-grid"><label v-if="fields.offer!=='rental'">Prix de vente<input v-model="fields.sale" inputmode="decimal" placeholder="18 500 000" required/></label><label v-if="fields.offer!=='sale'">Tarif de location / jour<input v-model="fields.rent" inputmode="decimal" placeholder="45 000" required/></label></div><p class="notice">Devise : {{ shop.currency.code==='XOF'?'FCFA':shop.currency.code }} — déterminée par le pays de votre boutique.</p></template><template v-if="step===2"><h2>Caractéristiques</h2><div class="form-grid"><label>Kilométrage<input v-model="fields.mileage_km" type="number" min="0"/></label><label>Carburant<select v-model="fields.fuel"><option value="petrol">Essence</option><option value="diesel">Diesel</option><option value="hybrid">Hybride</option><option value="electric">Électrique</option></select></label><label>Transmission<select v-model="fields.transmission"><option value="automatic">Automatique</option><option value="manual">Manuelle</option></select></label><label>Moteur<input v-model="fields.engine"/></label><label>Puissance (ch)<input v-model="fields.horsepower" type="number" min="1" max="3000"/></label><label>Portes<input v-model="fields.doors" type="number" min="1" max="10"/></label><label>Places<input v-model="fields.seats" type="number" min="1" max="60"/></label></div><label>Description<textarea v-model="fields.description" rows="5" maxlength="10000" required/></label><h3>Équipements</h3><div class="checkbox-grid"><label v-for="f in references.features" :key="f.id"><input v-model="fields.feature_ids" type="checkbox" :value="f.id"/>{{ f.label }}</label></div></template><template v-if="step===3"><h2>Localisation</h2><label>Pays<input :value="shop.location.country.name" readonly/></label><ProfileLocation v-model="fields" required/><div class="form-grid"><label>Latitude (facultatif)<input v-model="fields.latitude" type="number" step="any" min="-90" max="90"/></label><label>Longitude (facultatif)<input v-model="fields.longitude" type="number" step="any" min="-180" max="180"/></label></div><p class="help">Le véhicule reste dans le pays de la boutique. Renseignez les deux coordonnées ou aucune.</p></template><template v-if="step===4"><h2>Photos & publication</h2><PhotoManager v-model="photos" :vehicle="record" :disabled="busy" @reload="refreshPhotos"/><p class="help">Au moins une photo est nécessaire pour publier. Les photos sélectionnées seront envoyées à l’enregistrement.</p><div class="notice"><strong>{{ references.models.find(m=>m.id===fields.vehicle_model_id)?.name || 'Modèle à renseigner' }} · {{ fields.year }}</strong><p>{{ fields.offer==='sale'?'Vente':fields.offer==='rental'?'Location':'Vente et location' }} · {{ shop.currency.code }}</p><p v-if="record">Le véhicule existe déjà : {{ record.reference }}. Un nouvel essai mettra à jour cette même annonce.</p></div></template><div class="form-footer"><button v-if="step>0" type="button" class="button secondary" @click="step--">← Précédent</button><button v-if="step<4" type="button" class="button" @click="step++">Continuer →</button><template v-else><button class="button secondary" :disabled="busy" type="button" @click="save(false)">{{ busy?'Enregistrement…':'Enregistrer comme brouillon' }}</button><button class="button" :disabled="busy" type="button" @click="save(true)">{{ busy?'Enregistrement…':'Publier' }}</button></template></div></fieldset></form></template></AsyncState></template>